#!/usr/bin/env python3
"""Flat SVG illustrations for public/img/sports used by Intermediate 1 / 10A Sports & competitions (original artwork).
Run once: python3 scripts/draw-sports-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'sports'
OUT.mkdir(parents=True, exist_ok=True)
BG = lambda c='#e8f5e9': f'<rect width="64" height="64" rx="8" fill="{c}"/>'
GRASS = '<rect x="0" y="44" width="64" height="20" fill="#43a047"/><rect x="0" y="44" width="64" height="2" fill="#fff"/>'
PERSON = lambda x, y, shirt='#e63946': f'<circle cx="{x}" cy="{y}" r="4" fill="#f5c6a5"/><rect x="{x - 4}" y="{y + 4}" width="8" height="11" rx="2" fill="{shirt}"/><rect x="{x - 3}" y="{y + 15}" width="2.5" height="8" fill="#222"/><rect x="{x + .5}" y="{y + 15}" width="2.5" height="8" fill="#222"/>'
BALL = lambda x, y, r=5: f'<circle cx="{x}" cy="{y}" r="{r}" fill="#fff" stroke="#333" stroke-width="1.5"/><path d="M{x-2} {y-2} L{x+2} {y-2} L{x+3} {y+1} L{x} {y+3} L{x-3} {y+1}Z" fill="#333"/>'
TROPHY = lambda x, y, c='#ffd54a': f'<path d="M{x-10} {y} h20 v10 a10 10 0 0 1 -20 0z" fill="{c}"/><path d="M{x-10} {y+2} a5 5 0 0 1 -6 6 M{x+10} {y+2} a5 5 0 0 0 6 6" stroke="{c}" stroke-width="3" fill="none"/><rect x="{x-2}" y="{y+20}" width="4" height="6" fill="{c}"/><rect x="{x-8}" y="{y+26}" width="16" height="4" rx="1" fill="#8d5524"/>'
MEDAL = lambda x, y, c='#ffd54a': f'<path d="M{x-6} {y-14} L{x} {y-2} L{x+6} {y-14}" stroke="#e63946" stroke-width="5" fill="none"/><circle cx="{x}" cy="{y+4}" r="9" fill="{c}" stroke="#b8860b" stroke-width="1.5"/><text x="{x}" y="{y+8}" font-family="sans-serif" font-size="10" font-weight="bold" fill="#8d5524" text-anchor="middle">1</text>'
SCORE = lambda a, b: f'<rect x="10" y="10" width="44" height="18" rx="3" fill="#222"/><text x="22" y="24" font-family="monospace" font-size="13" font-weight="bold" fill="#ffd54a" text-anchor="middle">{a}</text><text x="32" y="24" font-family="monospace" font-size="11" fill="#fff" text-anchor="middle">-</text><text x="42" y="24" font-family="monospace" font-size="13" font-weight="bold" fill="#ffd54a" text-anchor="middle">{b}</text>'

ICONS = {
    'win': BG() + GRASS + PERSON(32, 14, '#4d96ff') + '<path d="M20 20 L24 10 M44 20 L40 10" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>' + TROPHY(32, 28, '#ffd54a').replace('y="54"', 'y="54"') + '<text x="52" y="16" font-family="sans-serif" font-size="12" fill="#ffd54a">★</text><text x="8" y="22" font-family="sans-serif" font-size="12" fill="#ffd54a">★</text>',
    'beat': BG() + GRASS + PERSON(18, 14, '#4d96ff') + PERSON(46, 20, '#e63946') + '<path d="M8 10 L16 6" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><text x="46" y="14" font-family="sans-serif" font-size="9" fill="#555" text-anchor="middle">...</text>' + SCORE(3, 0),
    'score': BG() + GRASS + '<rect x="40" y="22" width="20" height="22" fill="none" stroke="#fff" stroke-width="2"/><path d="M42 24 L58 42 M58 24 L42 42 M50 22 L50 44" stroke="#ddd" stroke-width="1"/>' + PERSON(14, 16, '#e63946') + BALL(50, 36, 4) + '<path d="M22 32 Q36 26 46 34" stroke="#333" stroke-width="1.5" fill="none" stroke-dasharray="2 2"/><text x="12" y="10" font-family="sans-serif" font-size="9" font-weight="bold" fill="#e63946">GOAL!</text>',
    'lose': BG('#eceff1') + GRASS + PERSON(32, 16, '#9e9e9e') + '<path d="M28 20 L26 32 M36 20 L38 32" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><path d="M28 18 Q32 22 36 18" stroke="#333" stroke-width="1.5" fill="none" transform="translate(0,-4) rotate(0)"/>' + SCORE(0, 4),
    'tie': BG() + GRASS + PERSON(16, 16, '#4d96ff') + PERSON(48, 16, '#e63946') + '<path d="M22 24 L42 24" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>' + SCORE(1, 1),
    'athlete': BG('#fff3e0') + '<rect x="0" y="48" width="64" height="16" fill="#d84315"/><rect x="0" y="52" width="64" height="1" fill="#fff"/><rect x="0" y="58" width="64" height="1" fill="#fff"/>' + '<circle cx="34" cy="14" r="4" fill="#f5c6a5"/><path d="M30 18 L36 30 L48 30" stroke="#4d96ff" stroke-width="5" stroke-linecap="round" fill="none"/><path d="M36 30 L26 44 M36 30 L48 40" stroke="#222" stroke-width="3.5" stroke-linecap="round"/><path d="M30 20 L20 26 M30 20 L42 18" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><text x="12" y="14" font-family="sans-serif" font-size="8" fill="#555">7</text>',
    'crowd': BG('#1e2a44') + ''.join(f'<circle cx="{x}" cy="{y}" r="3.5" fill="{c}"/><rect x="{x-4}" y="{y+3}" width="8" height="8" rx="2" fill="{s}"/>' for x, y, c, s in [(8, 40, '#f5c6a5', '#e63946'), (20, 42, '#8d5524', '#4d96ff'), (32, 40, '#f5c6a5', '#ffd54a'), (44, 42, '#f5c6a5', '#2e7d32'), (56, 40, '#8d5524', '#e63946'), (14, 26, '#f5c6a5', '#9c27b0'), (26, 28, '#f5c6a5', '#e63946'), (38, 26, '#8d5524', '#4d96ff'), (50, 28, '#f5c6a5', '#ffd54a')]) + '<path d="M10 18 L8 10 M56 18 L58 10" stroke="#f5c6a5" stroke-width="2.5" stroke-linecap="round"/><rect x="0" y="54" width="64" height="10" fill="#333"/>',
    'player': BG() + GRASS + PERSON(28, 14, '#4d96ff') + '<text x="28" y="26" font-family="sans-serif" font-size="7" font-weight="bold" fill="#fff" text-anchor="middle">10</text>' + BALL(40, 46, 5) + '<path d="M31 33 L38 42" stroke="#222" stroke-width="2.5" stroke-linecap="round"/>',
    'medal': BG('#fff8e1') + MEDAL(32, 32).replace('r="9"', 'r="14"').replace('font-size="10"', 'font-size="16"').replace('y="36"', 'y="42"').replace('L32 30', 'L32 22').replace('L26 18', 'L20 6').replace('L38 18', 'L44 6'),
    'race': BG('#fff3e0') + '<rect x="0" y="44" width="64" height="20" fill="#d84315"/><rect x="0" y="50" width="64" height="1" fill="#fff"/><rect x="0" y="57" width="64" height="1" fill="#fff"/><rect x="54" y="18" width="2" height="30" fill="#333"/><rect x="48" y="18" width="12" height="10" fill="#fff"/><path d="M48 18h3v3h-3zM54 18h3v3h-3zM51 21h3v3h-3zM57 21h3v3h-3zM48 24h3v3h-3zM54 24h3v3h-3z" fill="#333"/>' + '<circle cx="18" cy="24" r="3.5" fill="#f5c6a5"/><path d="M15 28 L20 38 L30 38" stroke="#e63946" stroke-width="4.5" stroke-linecap="round" fill="none"/><path d="M20 38 L12 50 M20 38 L30 46" stroke="#222" stroke-width="3" stroke-linecap="round"/>' + '<circle cx="34" cy="26" r="3.5" fill="#8d5524"/><path d="M31 30 L36 40 L46 40" stroke="#4d96ff" stroke-width="4.5" stroke-linecap="round" fill="none"/><path d="M36 40 L28 52 M36 40 L46 48" stroke="#222" stroke-width="3" stroke-linecap="round"/>',
    'referee': BG() + GRASS + '<circle cx="32" cy="12" r="4" fill="#f5c6a5"/><rect x="26" y="16" width="12" height="14" rx="2" fill="#222"/><path d="M28 16 v14 M32 16 v14 M36 16 v14" stroke="#fff" stroke-width="1.5"/><rect x="27" y="30" width="4" height="12" fill="#222"/><rect x="33" y="30" width="4" height="12" fill="#222"/><path d="M38 20 L48 10" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><rect x="45" y="4" width="8" height="10" rx="1" fill="#ffd54a"/><path d="M26 20 L18 24" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><circle cx="16" cy="25" r="2.5" fill="#333"/>',
    'spectator': BG('#1e2a44') + '<rect x="0" y="54" width="64" height="10" fill="#333"/><circle cx="32" cy="22" r="6" fill="#f5c6a5"/><rect x="22" y="28" width="20" height="18" rx="3" fill="#e63946"/><path d="M22 30 L12 22 M42 30 L52 22" stroke="#f5c6a5" stroke-width="4" stroke-linecap="round"/><rect x="6" y="12" width="12" height="9" fill="#ffd54a"/><rect x="46" y="12" width="12" height="9" fill="#4d96ff"/><path d="M28 24 Q32 27 36 24" stroke="#333" stroke-width="1.2" fill="none"/>',
    'umpire': BG('#e3f2fd') + '<rect x="0" y="44" width="64" height="20" fill="#43a047"/><rect x="24" y="14" width="4" height="36" fill="#999"/><rect x="28" y="20" width="4" height="30" fill="#999"/><rect x="18" y="4" width="16" height="12" rx="3" fill="#fff" stroke="#333"/><circle cx="26" cy="10" r="3" fill="#f5c6a5"/><rect x="20" y="13" width="12" height="4" fill="#4d96ff"/><path d="M4 24 L22 20 M22 20 L40 24" stroke="#fff" stroke-width="2"/><path d="M40 24 L60 20" stroke="#fff" stroke-width="2"/><circle cx="50" cy="40" r="4" fill="#c6ff00" stroke="#333" stroke-width="1"/>',
    'trophy': BG('#fff8e1') + TROPHY(32, 14).replace('rx="1"', 'rx="1"') + '<text x="32" y="26" font-family="sans-serif" font-size="8" font-weight="bold" fill="#8d5524" text-anchor="middle">1st</text><text x="10" y="14" font-family="sans-serif" font-size="12" fill="#ffd54a">★</text><text x="50" y="12" font-family="sans-serif" font-size="12" fill="#ffd54a">★</text>',
    'game': BG() + GRASS + '<rect x="4" y="22" width="12" height="22" fill="none" stroke="#fff" stroke-width="2"/><rect x="48" y="22" width="12" height="22" fill="none" stroke="#fff" stroke-width="2"/><circle cx="32" cy="36" r="6" fill="none" stroke="#fff" stroke-width="1.5"/>' + PERSON(22, 12, '#4d96ff') + PERSON(42, 12, '#e63946') + BALL(32, 46, 4),
    'take-part-in': BG('#e3f2fd') + '<path d="M8 10 L56 10 M8 10 l2 -3 l2 3 M52 7 L56 10 L52 13" stroke="#333" stroke-width="1" fill="none"/>' + ''.join(f'<circle cx="{x}" cy="{30}" r="3.5" fill="#f5c6a5"/><rect x="{x-4}" y="34" width="8" height="12" rx="2" fill="{c}"/><rect x="{x-5}" y="36" width="10" height="5" fill="#fff"/><text x="{x}" y="40" font-family="sans-serif" font-size="4" fill="#333" text-anchor="middle">{n}</text>' for x, c, n in [(12, '#e63946', 21), (24, '#4d96ff', 22), (36, '#ffd54a', 23), (48, '#2e7d32', 24)]) + '<circle cx="54" cy="18" r="6" fill="#fff" stroke="#333"/><text x="54" y="21" font-family="sans-serif" font-size="8" fill="#333" text-anchor="middle">5</text>',
    'cheat': BG('#fce4ec') + GRASS + PERSON(22, 14, '#4d96ff') + '<path d="M28 28 L40 40" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/>' + BALL(44, 44, 4) + '<text x="44" y="18" font-family="sans-serif" font-size="12" font-weight="bold" fill="#e63946" text-anchor="middle">✗</text><rect x="36" y="22" width="18" height="10" rx="2" fill="#fff" stroke="#e63946"/><text x="45" y="30" font-family="sans-serif" font-size="7" fill="#e63946" text-anchor="middle">HAND</text>',
    'warm-up': BG('#fff3e0') + '<rect x="0" y="48" width="64" height="16" fill="#d84315"/>' + '<circle cx="24" cy="14" r="4" fill="#f5c6a5"/><rect x="20" y="18" width="8" height="12" rx="2" fill="#2e7d32"/><path d="M20 20 L10 10 M28 20 L38 10" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><path d="M22 30 L14 46 M26 30 L34 46" stroke="#222" stroke-width="3" stroke-linecap="round"/><path d="M44 20 q4 -8 8 0 q4 -8 8 0" stroke="#e63946" stroke-width="2" fill="none"/><path d="M46 32 q4 -6 8 0" stroke="#e63946" stroke-width="2" fill="none"/>',
    'give-up': BG('#eceff1') + '<rect x="0" y="48" width="64" height="16" fill="#d84315"/><circle cx="30" cy="30" r="4" fill="#f5c6a5"/><rect x="24" y="34" width="12" height="10" rx="2" fill="#9e9e9e"/><path d="M24 44 L18 48 M36 44 L42 48" stroke="#222" stroke-width="3" stroke-linecap="round"/><path d="M26 38 L22 44 M34 38 L38 44" stroke="#f5c6a5" stroke-width="3" stroke-linecap="round"/><rect x="48" y="8" width="2" height="40" fill="#333"/><path d="M50 10 L62 14 L50 18Z" fill="#fff" stroke="#999"/><text x="12" y="16" font-family="sans-serif" font-size="8" fill="#555">20 km</text>',
}

for name, body in ICONS.items():
    (OUT / f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{body}</svg>\n')
print(f'{len(ICONS)} icons written to {OUT}')
